pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        // Bound amount to prevent overflow and keep it realistic; target can be any address
        vm.assume(amount > 0 && amount <= 1_000_000 ether);
        // Fund the owner
        address owner = c.owner();
        vm.deal(owner, amount);
        // Owner sends money to a target
        vm.prank(owner);
        c.sendMoney(target, amount);
        // Record contract balance before withdrawAll
        uint256 balanceBefore = address(c).balance;
        // Owner calls withdrawAll; wrap in try/catch to detect revert
        bool withdrawAllSucceeded;
        try c.withdrawAll() { withdrawAllSucceeded = true; } catch { withdrawAllSucceeded = false; }
        // If withdrawAll succeeded, the contract balance must be zero (all funds withdrawn).
        // If it reverted, the contract balance must remain unchanged.
        // In the correct version, withdrawAll succeeds and drains the balance.
        // In the buggy version, it always reverts, leaving the balance unchanged but violating the success path.
        // The general rule: it must NOT be that withdrawAll reverts AND the balance remains unchanged,
        // because the only case where balance stays the same is if it reverted, which never happens in the correct version.
        // To capture this: if withdrawAllSucceeded, then balance must be 0; the mutant never succeeds, so it will fail this assertion for some input.
        assertTrue(!withdrawAllSucceeded || address(c).balance == 0);
    }
}

